\chapter{{Filtrations, processes and martingales}}\label{chap:filtration_martingale}


\section{Basic definitions}

First, recall the definitions of a filtration, an adapted process, a (sub)martingale, a stopping time and a stopped process, which are already in Mathlib.


\begin{definition}[Filtration]\label{def:filtration}
  \mathlibok
  \lean{MeasureTheory.Filtration}
A filtration on a measurable space $(\Omega, \mathcal{A})$ with measure $P$ indexed by a preordered set $T$ is a family of sigma-algebras $\mathcal{F} = (\mathcal{F}_t)_{t \in T}$ such that for all $i \le j$, $\mathcal{F}_i \subseteq \mathcal{F}_j$ and for all $t \in T$, $\mathcal{F}_t \subseteq \mathcal{A}$.
\end{definition}


\begin{definition}\label{def:adapted}
  \uses{def:filtration}
  \mathlibok
  \lean{MeasureTheory.Adapted}
A process $X : T \to \Omega \to E$ is said to be adapted with respect to a filtration $\mathcal{F}$ if for all $t \in T$, $X_t$ is $\mathcal{F}_t$-measurable.
\end{definition}


\begin{definition}[Progressively measurable]\label{def:IsStronglyProgressive}
  \uses{def:filtration}
  \mathlibok
  \lean{MeasureTheory.IsStronglyProgressive}
A stochastic process $X$ is said to be progressively measurable with respect to a filtration $\mathcal{F}$ if at each point in time $i$, $X$ restricted to $(-\infty, i] \times \Omega$ is measurable with respect to the product $\sigma$-algebra where the $\sigma$-algebra used for $\Omega$ is $\mathcal{F}_i$.
\end{definition}

\begin{definition}[Right continuous function]\label{def:RightContinuous}
  \leanok
  \lean{Function.IsRightContinuous}
  Let $T$ be equipped with a partial order and $f : T \to E$ be a function. Then $f$ is right
  continuous if for all $t \in T$, $\lim_{s \downarrow t} f(s) = f(t)$.
\end{definition}

\begin{definition}[Cadlag function]\label{def:IsCadlag}
  \uses{def:RightContinuous}
  \leanok
  \lean{IsCadlag}
  A function $f : T \to E$ is cadlag if it is right continuous and the limit $\lim_{s \uparrow t} f(s)$ exists for all $t \in T$.
\end{definition}


\begin{lemma}\label{lem:Adapted.isStronglyProgressive_of_rightContinuous}
  \uses{def:adapted, def:IsStronglyProgressive, def:RightContinuous}
  \leanok
  \lean{MeasureTheory.StronglyAdapted.isStronglyProgressive_of_rightContinuous}
Suppose $T$ is a linearly ordered set equipped with the order topology. If $T$ is second countable and a stochastic process $(X_t)_{t \in T}$ is right continuous and adapted, then it is progressively measurable.
\end{lemma}

\begin{proof}
  \leanok
  Fixing $t \in T$, let $S$ be a union of a dense set of $(-\infty,t]$ and the set of points isolated from right in $(-\infty,t]$.
  As $T$ is second countable, $S$ can be chosen so that it is countable, which means that there exists a surjective function $u: \mathbb{N} \rightarrow S$.
  We need to show that $X$ restricted to $(-\infty, t] \times \Omega$ is measurable with respect to $\mathcal{B}((-\infty, t]) \otimes \mathcal{F}_t$.
  To this end, we rearrange the image of the first $n$ numbers under the map $u$ in nondecreasing order, denoted by $v_0\le v_1\le \cdots\le v_n$,
  and define a left continuous discrete approximation of $X$ on $(-\infty, t]$ by
  $$X^n_s = \begin{cases}
    X_{v_0} & \text{if } s \le v_0 \\
    X_{v_i} & \text{if } s \in (- v_{i-1}, v_i]
  \end{cases}$$
  As $X$ is right continuous, it is easy to see that $X^n \to X$ pointwise as $n \to \infty$.
  Thus, as each $X^n$ is measurable, it follows that $X$ is also measurable (by using \verb|stronglyMeasurable_of_tendsto|).
\end{proof}


\begin{definition}[Martingale]\label{def:Martingale}
  \uses{def:adapted}
  \mathlibok
  \lean{MeasureTheory.Martingale}
Let $\mathcal{F}$ be a filtration on a measurable space $\Omega$ with measure $P$ indexed by $T$.
A family of functions $M : T \to \Omega \to E$ is a martingale with respect to a filtration $\mathcal{F}$ if $M$ is adapted with respect to $\mathcal{F}$ and for all $i \le j$, $P[M_j \mid \mathcal{F}_i] = M_i$ almost surely.
\end{definition}


\begin{definition}[Submartingale]\label{def:Submartingale}
  \uses{def:adapted}
  \mathlibok
  \lean{MeasureTheory.Submartingale}
Let $\mathcal{F}$ be a filtration on a measurable space $\Omega$ with measure $P$ indexed by $T$.
A family of functions $M : T \to \Omega \to E$ is a submartingale with respect to a filtration $\mathcal{F}$ if $M$ is adapted with respect to $\mathcal{F}$ and for all $i \le j$, $P[M_j \mid \mathcal{F}_i] \ge M_i$ almost surely.
\end{definition}

\begin{lemma}\label{lem:condExp_sub_nonneg}
  \uses{def:Submartingale}
  \mathlibok
  \lean{MeasureTheory.Submartingale.condExp_sub_nonneg}
Let $X$ be a real-valued submartingale with respect to a filtration $\mathcal{F}$. Then for all $i \le j$, we have $0 \le P[M_j - M_i \mid \mathcal{F}_i]$ almost surely.
\end{lemma}

\begin{proof}\mathlibok

\end{proof}


\begin{lemma}\label{lem:Submartingale.integrable_stoppedValue}
  \uses{def:Submartingale, def:stoppedProcess}
  \mathlibok
  \lean{MeasureTheory.Submartingale.integrable_stoppedValue}
Let $X$ be a submartingale. Then for all bounded stopping times $\tau$, the stopped value $X_\tau$ is integrable.
\end{lemma}

\begin{proof}\leanok

\end{proof}


\begin{lemma}\label{lem:Martingale.congr}
  \uses{def:Martingale, def:adapted}
  \leanok
  \lean{MeasureTheory.Martingale.congr}
If $X$ is a martingale and $Y$ is an adapted modification of $X$, then $Y$ is a martingale.
\end{lemma}

\begin{proof}\leanok
Let $i \le j$ in $T$. We want to show that $P[Y_j \mid \mathcal{F}_i] = Y_i$ almost surely.
It suffices to show that $\int_A Y_j \: dP = \int_A Y_i \: dP$ for all $A \in \mathcal{F}_i$.
Let then $A \in \mathcal{F}_i$.
\begin{align*}
  \int_A Y_j \: dP
  &= \int_A X_j \: dP
  = \int_A X_i \: dP
  = \int_A Y_i \: dP
  \: .
\end{align*}
\end{proof}


\chapter{Debut Theorem}
\label{chap:debut_theorem}


\section{Choquet's capacitability theorem}

This section is devoted to the proof of Choquet's capacitability theorem, which is a key ingredient in the proof of the debut theorem. The presentation follows \cite{bichteler2002stochastic} for the definition of analytic sets (that definition changes a lot between sources) and for the general proof steps, and \cite{he2019semimartingale} and the PlanetMath website for many of the proofs of individual lemmas.
Although the definition of analytic sets in \cite{he2019semimartingale} is different, the proofs follow the same general steps and the same ideas, and that book is much more detailed than \cite{bichteler2002stochastic}.

\subsection{Pavings and Compact systems}

A paving is simply a set of sets.

\begin{definition}\label{def:image2_prod}
  \mathlibok
  % no \lean{}: it's Set.image2 of a product
The product of two pavings $S$ and $T$ is the set of sets of the form $s \times t$ where $s \in S$ and $t \in T$. We denote that product by $S \times T$.
\end{definition}


\begin{definition}\label{def:supClosure}
  \mathlibok
  \lean{supClosure}
For a paving $S$, we denote by $S^{\cup f}$ the set of finite unions of sets in $S$.
\end{definition}


\begin{definition}\label{def:infClosure}
  \mathlibok
  \lean{infClosure}
For a paving $S$, we denote by $S^{\cap f}$ the set of finite intersections of sets in $S$.
\end{definition}


\begin{definition}\label{def:countableSupClosure}
  \leanok
  \lean{countableSupClosure}
We denote by $S_\sigma$ the set of countable unions of sets in $S$.
\end{definition}


\begin{definition}\label{def:countableInfClosure}
  \leanok
  \lean{countableInfClosure}
We denote by $S_\delta$ the set of countable intersections of sets in $S$.
\end{definition}


\begin{lemma}\label{lem:InfClosed.mem_countableInfClosure_iff}
  \uses{def:countableInfClosure}
  \leanok
  \lean{InfClosed.mem_countableInfClosure_iff}
If a paving $S$ is closed under pairwise intersection, then a set $s$ is in $S_\delta$ if and only if there exists a monotone decreasing family of sets $(A_n)_{n\in\mathbb{N}}$ in $S$ such that $s = \bigcap_{n\in\mathbb{N}} A_n$.
\end{lemma}

\begin{proof}\leanok
The ``monotone decreasing'' condition is the only non-trivial part of the statement: without it it would just be the definition of $S_\delta$.
If $s \in S_\delta$ there exists a family $(B_n)$ that satisfies the condition but may not be monotone. We can then define $A_n = \bigcap_{k \le n} B_k$, and the family $(A_n)$ is monotone decreasing and satisfies $\bigcap_{n\in\mathbb{N}} A_n = \bigcap_{n\in\mathbb{N}} B_n = s$.
\end{proof}


\begin{lemma}\label{lem:SupClosed.mem_countableSupClosure_iff}
  \uses{def:countableSupClosure}
  \leanok
  \lean{SupClosed.mem_countableSupClosure_iff}
If a paving $S$ is closed under pairwise union, then a set $s$ is in $S_\sigma$ if and only if there exists a monotone increasing family of sets $(A_n)_{n\in\mathbb{N}}$ in $S$ such that $s = \bigcup_{n\in\mathbb{N}} A_n$.
\end{lemma}

\begin{proof}\leanok
Similar to the proof of Lemma~\ref{lem:InfClosed.mem_countableInfClosure_iff}.
\end{proof}


\begin{definition}\label{def:IsCompactSystem}
  \mathlibok
  \lean{IsCompactSystem}
A set of sets $K$ is a compact system if for every countable family $(C_n)_{n \in \mathbb{N}}$ of sets in $K$ such that $\bigcap_{n \in\mathbb{N}} C_n = \emptyset$, there exists a finite subset $S$ of $\mathbb{N}$ such that $\bigcap_{n \in S} C_n = \emptyset$.
\end{definition}


\begin{lemma}\label{lem:isCompactSystem_isCompact_isClosed}
  \uses{def:IsCompactSystem}
  \leanok
  \lean{isCompactSystem_isCompact_isClosed}
The family of compact closed sets of a topological space is a compact system.
\end{lemma}

\begin{proof}\leanok
  \uses{def:IsCompactSystem}

\end{proof}


\begin{lemma}\label{lem:isCompactSystem_isCompact}
  \uses{def:IsCompactSystem}
  \leanok
  \lean{isCompactSystem_isCompact}
The family of compact sets of a T2 topological space is a compact system.
\end{lemma}

\begin{proof}\leanok
  \uses{lem:isCompactSystem_isCompact_isClosed}
The T2 assumption ensures that compact sets are closed, so the family of compact sets is the family of compact closed sets, which is a compact system by Lemma~\ref{lem:isCompactSystem_isCompact_isClosed}.
\end{proof}


\begin{lemma}\label{lem:IsCompactSystem.mono}
  \uses{def:IsCompactSystem}
  \leanok
  \lean{IsCompactSystem.mono}
If $S \subseteq T$ and $T$ is a compact system, then $S$ is a compact system.
\end{lemma}

\begin{proof}\leanok
  \uses{def:IsCompactSystem}
Any sequence of sets in $S$ is a sequence of sets in $T$, so if the intersection of the sequence is empty, then there is a finite subset of the sequence whose intersection is empty by the compact system property of $T$.
\end{proof}


